/**
 * One-off: re-encode stored hero images as AVIF.
 *
 * Images were generated as 1024px PNGs and stored as data: URLs (~2MB each).
 * A data: URL in a server-rendered page is inlined into both the HTML and the
 * RSC payload, so a single article made /resources a 4.3MB response. AVIF at
 * the same dimensions is a fraction of that.
 *
 * Idempotent: rows already holding image/avif are skipped, so this is safe to
 * re-run after new images are generated by an older build.
 */
import pg from "pg";
import sharp from "sharp";

const db = new pg.Pool({ connectionString: process.env.DATABASE_URL });

async function convert(table) {
  const { rows } = await db.query(
    `SELECT id, slug, image_url FROM ${table}
      WHERE image_url LIKE 'data:image/%' AND image_url NOT LIKE 'data:image/avif%'`,
  );
  for (const row of rows) {
    const base64 = row.image_url.slice(row.image_url.indexOf(",") + 1);
    const before = Buffer.from(base64, "base64");
    const after = await sharp(before)
      .resize({ width: 1800, withoutEnlargement: true })
      .avif({ quality: 55, effort: 4 })
      .toBuffer();
    await db.query(`UPDATE ${table} SET image_url = $1 WHERE id = $2`, [
      `data:image/avif;base64,${after.toString("base64")}`,
      row.id,
    ]);
    const pct = ((1 - after.length / before.length) * 100).toFixed(1);
    console.log(`${table}/${row.slug}: ${(before.length / 1024).toFixed(0)}KB -> ${(after.length / 1024).toFixed(0)}KB (-${pct}%)`);
  }
  if (rows.length === 0) console.log(`${table}: nothing to convert`);
}

await convert("articles");
await convert("research_reports");
await db.end();
